  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "A CF3-containing heteroaromatic PET tracer (18F-JNJ-64413739) showed high brain uptake and fast kinetics in rodents and non-human primates, supporting that similar CF3-heteroaromatic small molecules can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A morpholine-substituted aromatic compound (compound 33) showed excellent CNS penetration with a brain-to-plasma Kp of 11.4 and negligible P-gp efflux in mice, directly supporting CNS access for morpholine-containing analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A morpholine-containing compound (PRE-084) was rapidly distributed to the CNS in mice with brain concentrations exceeding plasma at Tmax, supporting that morpholine motifs do not preclude meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A CF3-containing heteroaromatic PET tracer ([11C]13) accumulated in brain regions in rats, demonstrating that CF3-heteroaromatic structures similar to the query can cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small molecule with a trifluoromethyl aniline and a dimorpholino-triazine core. Direct in vivo evidence from structurally related CF3-heteroaromatic and morpholine-containing compounds consistently shows meaningful brain penetration, with no contradictory evidence. The balance of transferable experimental data supports a pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain or CSF measurement exists for the exact query molecule.",
    "The query contains two morpholine groups, which increase polar surface area and may reduce passive permeability relative to the single-morpholine analogues; the impact is not directly quantified.",
    "No efflux-transporter data are available for the query itself, although a closely related morpholine analogue showed negligible P-gp efflux."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
